1	package govflow
2	
3	import (
4		"encoding/json"
5		"errors"
6		"math"
7		"os"
8		"path/filepath"
9		"strings"
10		"sync"
11		"testing"
12	)
13	
14	func baseVoteInput(id string) *CreateVoteInput {
15		return &CreateVoteInput{
16			ID: id,
17			Members: []VoteMember{
18				{ID: "alice", Weight: 300},
19				{ID: "bob", Weight: 200},
20				{ID: "carol", Weight: 100},
21				{ID: "dave", Weight: 400},
22			},
23			Delegations: []Delegation{{From: "bob", To: "alice"}, {From: "carol", To: "alice"}},
24			Quorum:      600,
25			StartAt:     100,
26			Deadline:    200,
27			TimelockEnd: 300,
28			Actions:     []string{"transfer:audits:100"},
29		}
30	}
31	
32	func mustCreateVote(t *testing.T, store *Store, in *CreateVoteInput) *VoteProposalView {
33		t.Helper()
34		view, existed, err := store.CreateVoteProposal(in)
35		if err != nil || existed {
36			t.Fatalf("CreateVoteProposal(%s) existed=%v err=%v", in.ID, existed, err)
37		}
38		return view
39	}
40	
41	func TestCreateVoteValidation(t *testing.T) {
42		store, _ := openTempStore(t, 1000)
43		defer store.Close()
44	
45		cases := []struct {
46			name   string
47			mutate func(in *CreateVoteInput)
48			want   error
49		}{
50			{"empty id", func(in *CreateVoteInput) { in.ID = "" }, ErrInvalidProposal},
51			{"no members", func(in *CreateVoteInput) { in.Members = nil }, ErrInvalidProposal},
52			{"empty member id", func(in *CreateVoteInput) { in.Members[0].ID = "" }, ErrInvalidProposal},
53			{"duplicate member", func(in *CreateVoteInput) { in.Members[1].ID = "alice" }, ErrInvalidProposal},
54			{"zero weight", func(in *CreateVoteInput) { in.Members[2].Weight = 0 }, ErrInvalidProposal},
55			{"negative weight", func(in *CreateVoteInput) { in.Members[2].Weight = -5 }, ErrInvalidProposal},
56			{"quorum zero", func(in *CreateVoteInput) { in.Quorum = 0 }, ErrInvalidProposal},
57			{"quorum over total", func(in *CreateVoteInput) { in.Quorum = 1001 }, ErrInvalidProposal},
58			{"negative start", func(in *CreateVoteInput) { in.StartAt = -1 }, ErrInvalidProposal},
59			{"start equals deadline", func(in *CreateVoteInput) { in.StartAt = 200 }, ErrInvalidProposal},
60			{"deadline after timelock", func(in *CreateVoteInput) { in.TimelockEnd = 199 }, ErrInvalidProposal},
61			{"start zero ok boundary", func(in *CreateVoteInput) { in.StartAt = 0; in.Deadline = 1; in.TimelockEnd = 1 }, nil},
62			{"self delegation", func(in *CreateVoteInput) {
63				in.Delegations = append(in.Delegations, Delegation{From: "alice", To: "alice"})
64			}, ErrInvalidProposal},
65			{"unknown delegator", func(in *CreateVoteInput) { in.Delegations[0].From = "ghost" }, ErrInvalidProposal},
66			{"unknown delegatee", func(in *CreateVoteInput) { in.Delegations[0].To = "ghost" }, ErrInvalidProposal},
67			{"double delegation", func(in *CreateVoteInput) {
68				in.Delegations = append(in.Delegations, Delegation{From: "bob", To: "dave"})
69			}, ErrInvalidProposal},
70			{"delegation cycle", func(in *CreateVoteInput) {
71				in.Delegations = []Delegation{{From: "alice", To: "bob"}, {From: "bob", To: "alice"}}
72			}, ErrInvalidProposal},
73			{"delegation cycle length three", func(in *CreateVoteInput) {
74				in.Delegations = []Delegation{{From: "alice", To: "bob"}, {From: "bob", To: "carol"}, {From: "carol", To: "alice"}}
75			}, ErrInvalidProposal},
76			{"total weight overflow", func(in *CreateVoteInput) {
77				in.Members = []VoteMember{{ID: "a", Weight: math.MaxInt64}, {ID: "b", Weight: 1}}
78			}, ErrInvalidProposal},
79		}
80		for _, tc := range cases {
81			t.Run(tc.name, func(t *testing.T) {
82				in := baseVoteInput("vc-" + strings.ReplaceAll(tc.name, " ", "-"))
83				tc.mutate(in)
84				_, existed, err := store.CreateVoteProposal(in)
85				if tc.want == nil {
86					if err != nil {
87						t.Fatalf("unexpected error: %v", err)
88					}
89					return
90				}
91				if err == nil || existed {
92					t.Fatalf("expected rejection, existed=%v err=%v", existed, err)
93				}
94				if !errors.Is(err, tc.want) {
95					t.Fatalf("err=%v, want %v", err, tc.want)
96				}
97			})
98		}
99	
100		// 非法创建不得留下任何记录。
101		if all, _ := store.VoteProposals(); len(all) != 1 {
102			t.Fatalf("failed creates left records: %d", len(all))
103		}
104	}
105	
106	func TestCreateVoteIdempotentAndConflict(t *testing.T) {
107		store, _ := openTempStore(t, 1000)
108		defer store.Close()
109		in := baseVoteInput("gip-v")
110		mustCreateVote(t, store, in)
111	
112		// 相同编号、成员与委托换序、动作同序：视为完全相同。
113		retry := baseVoteInput("gip-v")
114		retry.Members = []VoteMember{
115			{ID: "dave", Weight: 400}, {ID: "carol", Weight: 100},
116			{ID: "bob", Weight: 200}, {ID: "alice", Weight: 300},
117		}
118		retry.Delegations = []Delegation{{From: "carol", To: "alice"}, {From: "bob", To: "alice"}}
119		view, existed, err := store.CreateVoteProposal(retry)
120		if err != nil || !existed {
121			t.Fatalf("reordered retry existed=%v err=%v", existed, err)
122		}
123		if view.State != "voting" {
124			t.Fatalf("retry changed state: %s", view.State)
125		}
126	
127		diffs := map[string]func(*CreateVoteInput){
128			"weight changed":    func(x *CreateVoteInput) { x.Members[0].Weight = 301 },
129			"member changed":    func(x *CreateVoteInput) { x.Members[3].ID = "davina" },
130			"quorum changed":    func(x *CreateVoteInput) { x.Quorum = 599 },
131			"start changed":     func(x *CreateVoteInput) { x.StartAt = 99 },
132			"deadline changed":  func(x *CreateVoteInput) { x.Deadline = 201 },
133			"timelock changed":  func(x *CreateVoteInput) { x.TimelockEnd = 301 },
134			"action text":       func(x *CreateVoteInput) { x.Actions = []string{"transfer:audits:99"} },
135			"action order":      func(x *CreateVoteInput) { x.Actions = []string{"transfer:legal:1", "transfer:audits:100"} },
136			"action removed":    func(x *CreateVoteInput) { x.Actions = nil },
137			"delegation target": func(x *CreateVoteInput) { x.Delegations[0].To = "dave" },
138			"delegation added":  func(x *CreateVoteInput) { x.Delegations = append(x.Delegations, Delegation{From: "dave", To: "alice"}) },
139		}
140		for name, mut := range diffs {
141			t.Run(name, func(t *testing.T) {
142				x := baseVoteInput("gip-v")
