	in := &CreateVoteInput{
		ID:      "gip-ordered-chain",
		Members: []VoteMember{{ID: "b", Weight: 2}, {ID: "c", Weight: 4}, {ID: "a", Weight: 1}, {ID: "d", Weight: 8}},
		Delegations: []Delegation{
			{From: "a", To: "b"},
			{From: "b", To: "c"},
